exam.task:
Gib für jede Zeile 1–8 die Ausgabe an (je 1,25 P).
<div class="code "><div class="ct">Gegeben</div><pre><span class="k">class</span> <span class="t">A</span> {
    <span class="t">String</span> name = <span class="s">&quot;A&quot;</span>;
    <span class="k">static</span> <span class="t">String</span> s()          { <span class="k">return</span> <span class="s">&quot;A.s&quot;</span>; }
    <span class="t">String</span> m(<span class="t">Object</span> o)         { <span class="k">return</span> <span class="s">&quot;A.m(Object)&quot;</span>; }
    <span class="t">String</span> m(<span class="t">A</span> a)              { <span class="k">return</span> <span class="s">&quot;A.m(A)&quot;</span>; }
    <span class="t">String</span> who()               { <span class="k">return</span> <span class="s">&quot;A.who&quot;</span>; }
    <span class="t">String</span> call()              { <span class="k">return</span> who(); }
}
<span class="k">class</span> <span class="t">B</span> <span class="k">extends</span> <span class="t">A</span> {
    <span class="t">String</span> name = <span class="s">&quot;B&quot;</span>;
    <span class="k">static</span> <span class="t">String</span> s()          { <span class="k">return</span> <span class="s">&quot;B.s&quot;</span>; }
    <span class="a">@Override</span> <span class="t">String</span> m(<span class="t">A</span> a)    { <span class="k">return</span> <span class="s">&quot;B.m(A)&quot;</span>; }
    <span class="t">String</span> m(<span class="t">B</span> b)              { <span class="k">return</span> <span class="s">&quot;B.m(B)&quot;</span>; }
    <span class="a">@Override</span> <span class="t">String</span> who()     { <span class="k">return</span> <span class="s">&quot;B.who&quot;</span>; }
}
<span class="t">A</span> x = <span class="k">new</span> <span class="t">B</span>();  <span class="t">B</span> y = <span class="k">new</span> <span class="t">B</span>();
<span class="t">System</span>.out.println(x.name);         <span class="c">// 1</span>
<span class="t">System</span>.out.println(((<span class="t">B</span>) x).name);   <span class="c">// 2</span>
<span class="t">System</span>.out.println(x.s());          <span class="c">// 3</span>
<span class="t">System</span>.out.println(x.call());       <span class="c">// 4</span>
<span class="t">System</span>.out.println(x.m(y));         <span class="c">// 5</span>
<span class="t">System</span>.out.println(y.m(y));         <span class="c">// 6</span>
<span class="t">System</span>.out.println(y.m(x));         <span class="c">// 7</span>
<span class="t">System</span>.out.println(x.m(<span class="s">&quot;hi&quot;</span>));      <span class="c">// 8</span></pre></div>

